// internal/distributed/proxy/httpserver/timeout_middleware.go lines 182-186
	timeout := paramtable.Get().HTTPCfg.RequestTimeoutMs.GetAsDuration(time.Millisecond)
	timeoutSecond, err := strconv.ParseInt(gCtx.Request.Header.Get(mhttp.HTTPHeaderRequestTimeout), 10, 64)
	if err == nil {
		timeout = time.Duration(timeoutSecond) * time.Second
	}

// CRITICAL: No validation of timeoutSecond value (negative check, range check, or error handling)
// When ParseInt fails (non-numeric like 'abc'), err != nil, code falls back to default timeout silently
// No HTTP 400 returned for malformed header value
